// Social UI in Game Feature

var moduleRoot = __webpack_require__(5572).root;
var map1 = __webpack_require__(6409).map1;
var moduleHomeScreen = __webpack_require__(9216).homeScreen;

var c_friendsButtonElement = document.getElementById("btnFriends");
var c_originalMouseDownFunc = null

c_homeUIElement.style.display = "block";

document.addEventListener("keydown", function(event) {
  if (event.code === "ControlRight") {
    c_hasPressedCtrlRKey = true;
  }

  if (
    c_hasPressedCtrlRKey && event.code === "Slash"
    && moduleRoot.game.map && moduleRoot.game.map !== map1
  ) {
    c_hasSocialUICoveredInGame = !c_hasSocialUICoveredInGame;

    if (c_hasSocialUICoveredInGame) {
      c_homeUIElement.style.display = "block";
      c_homeMainWindowElement.style.display = "none";
      c_slayTVElement.style.display = "none";
      c_friendsButtonElement.style.display = "block";
  
      c_originalMouseDownFunc = document.documentElement.onmousedown;
      document.documentElement.onmousedown = (e) => {};
    } else {
      c_homeUIElement.style.display = "none";
      c_friendsButtonElement.style.display = "none";
      document.documentElement.onmousedown = c_originalMouseDownFunc;
    }
  }
});

document.addEventListener("keyup", function(event) {
  if (event.code === "ControlRight") {
    c_hasPressedCtrlRKey = false;
  }
});

c_socialChatInputElement.addEventListener("click", function(event) {
  c_socialChatInputElement.focus();
});

c_socialChatInputElement.addEventListener("keypress", function (e) {
  if (10 === e.which || 13 === e.which) {
    var value = c_socialChatInputElement.value.trim();
    if (!(value.length <= 0)) {
      var activeFriendId = moduleHomeScreen.getActiveFriendChatId();
      (null !== activeFriendId
        ? window.dispatchEvent(
            new CustomEvent("friendChatSend", {
              detail: { id: activeFriendId, message: value },
            }),
          )
        : window.dispatchEvent(
            new CustomEvent("globalChatSend", {
              detail: { channel: moduleHomeScreen.activeChatChannel, message: value },
            }),
          ),
        (c_socialChatInputElement.value = ""));
    }
  }
});

// Account Changing Feature

var moduleOptionsScreen = __webpack_require__(1337).optionsScreen;
var moduleNetwork = __webpack_require__(7028).Network;
var logOutFunction = __webpack_require__(2399).logout;


var originalShowWindow = moduleOptionsScreen.showWindow;
var originalOnLoginSuccess = moduleNetwork.onLoginSuccess;
var originalSend = moduleNetwork.send;

var serverOption = document.getElementsByClassName('labelledContainer')[3];
var accountOption = serverOption.cloneNode(true);
var accountDD = accountOption.children[1];
var accountsStr = localStorage.getItem("accounts");
var accounts = [];

if (accountsStr && accountsStr.length > 0) {
	accounts = JSON.parse(accountsStr);
}

var lastLoginName = "";
var lastLoginPass = "";

accountOption.children[1].id = 'accountDropdown';
accountOption.children[0].innerText = 'ACCOUNT';

serverOption.parentNode.appendChild(accountOption);


function containsAccount(account) {
	for (var i = 0; i < accounts.length; i++) {
		if (accounts[i].name === account.name) {
			return i;
		}
	}
	return -1;
}

function renderAccountSwitch() {
	for ( ; accountDD.firstChild !== null; ) {
		accountDD.removeChild(accountDD.firstChild);
	}
	
	var val = -1;
	
	for (var i = 0; i < accounts.length; i++) {
		var option = document.createElement("option");
		option.innerText = accounts[i].name;
		option.value = i,
		accountDD.appendChild(option);
		
		if (accounts[i].name === lastLoginName) {
			val = i;
		}
	}
	accountDD.value = val;
}

accountDD.onchange = function() {
	var account = accounts[accountDD.value];
	
	logOutFunction();
	moduleNetwork.login(account.name, account.password);
	
	//moduleOptionsScreen.hideWindow();
}

moduleNetwork.send = function(msg) {
	var arr = msg.split('$');
	if (arr[0] === "login") {
		lastLoginName = arr[1];
		lastLoginPass = arr[2];
	}
	
	originalSend.call(this, msg);
}

moduleNetwork.onLoginSuccess = function() {
	var account = { name: lastLoginName, password: lastLoginPass };
	var prevAccStr = JSON.stringify(accounts);
	var accStr = prevAccStr;
	var i = containsAccount(account);
	
	if (i === -1) {
		accounts.push(account); 
		accStr = JSON.stringify(accounts);
	}
	else accounts[i] = account;
	
	var accStr = JSON.stringify(accounts);
		
	if (prevAccStr !== accStr)
		localStorage.setItem("accounts", JSON.stringify(accounts));
	
  localStorage.setItem("autologin", `${account.name}$${account.password}`)

	originalOnLoginSuccess.call(this);
}

document.addEventListener('keydown', function(event) {
	var popupBackground = document.getElementById("popupBG");
	
    if (event.key === 'Delete' && event.ctrlKey && !popupBackground.style.display) {
		if (accountDD.value !== -1) {
			accounts.splice(accountDD.value, 1);
			accountDD.remove(accountDD.value);
			accountDD.value = -1;
			
			localStorage.setItem("accounts", JSON.stringify(accounts));
		}
    }
	
});

moduleOptionsScreen.showWindow = function() {
	renderAccountSwitch();
	originalShowWindow.call(this);
}

